-- a text that spans several lines (a tooltip: text .. "\n\n" .. about) is also
-- known line by line, when the Russian has the same number of lines
local lines = function(s)
  local t, n = {}, 0
  for l in string.gfind(s .. "\n", "(.-)\n") do n = n + 1 t[n] = l end
  return t, n
end
local extra = {}
for k, v in pairs(words) do
  if string.find(k, "\n", 1, true) then
    local a, na = lines(k)
    local b, nb = lines(v)
    if na == nb then
      for i = 1, na do
        if a[i] ~= "" and string.find(a[i], "%a%a") and a[i] ~= b[i] then extra[a[i]] = b[i] end
      end
    end
  end
end
for k, v in pairs(extra) do if words[k] == nil then words[k] = v end end
for k, v in pairs(words) do if rawget(T, k) == nil then T[k] = v end end
